// Data-driven C4 System Context SVG renderer.
// Fed by the parsed Structurizr model (SystemContext view).

function esc(t) {
  return String(t)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// C4 standard palette
const C = {
  personBg: '#438DD5', personBorder: '#1168BD',
  systemBg: '#85BBF0', systemBorder: '#438DD5',
  rel: '#818892', title: '#2d2d2d', text: '#1a1a1a', sub: '#333333'
};

function personBox(e) {
  const icx = e.cx, icy = e.y + 55;
  let s = '<g>';
  s += `<rect x="${e.x}" y="${e.y}" width="${e.w}" height="${e.h}" rx="12" fill="${C.personBg}" stroke="${C.personBorder}" stroke-width="2.5"/>`;
  // person bust icon (head + shoulders)
  s += `<circle cx="${icx}" cy="${icy - 14}" r="15" fill="#ffffff"/>`;
  s += `<path d="M ${icx - 24} ${icy + 26} Q ${icx - 24} ${icy - 4} ${icx} ${icy - 4} Q ${icx + 24} ${icy - 4} ${icx + 24} ${icy + 26} Z" fill="#ffffff"/>`;
  s += `<text x="${e.cx}" y="${e.y + 118}" text-anchor="middle" font-size="20" font-weight="bold" fill="#ffffff">${esc(e.name)}</text>`;
  s += `<text x="${e.cx}" y="${e.y + 144}" text-anchor="middle" font-size="13" fill="#eaf2fb">${esc(e.description)}</text>`;
  s += '</g>';
  return s;
}

function systemBox(e) {
  let s = '<g>';
  s += `<rect x="${e.x}" y="${e.y}" width="${e.w}" height="${e.h}" rx="12" fill="${C.systemBg}" stroke="${C.systemBorder}" stroke-width="2.5"/>`;
  s += `<text x="${e.cx}" y="${e.cy - 4}" text-anchor="middle" font-size="20" font-weight="bold" fill="${C.text}">${esc(e.name)}</text>`;
  s += `<text x="${e.cx}" y="${e.cy + 24}" text-anchor="middle" font-size="13" fill="${C.sub}">${esc(e.description)}</text>`;
  s += '</g>';
  return s;
}

function relationship(r, pos) {
  const a = pos[r.sourceId], b = pos[r.destId];
  let x1, y1, x2, y2;
  if (a.cx < b.cx) { x1 = a.x + a.w; y1 = a.cy; x2 = b.x; y2 = b.cy; }
  else { x1 = a.x; y1 = a.cy; x2 = b.x + b.w; y2 = b.cy; }
  const dir = x2 > x1 ? 1 : -1;
  const headLen = 16, headW = 8;
  const hx = x2 - dir * headLen;
  const mx = (x1 + x2) / 2;
  let s = '<g>';
  s += `<line x1="${x1}" y1="${y1}" x2="${hx}" y2="${y2}" stroke="${C.rel}" stroke-width="2.5"/>`;
  s += `<polygon points="${x2},${y2} ${hx},${y2 - headW} ${hx},${y2 + headW}" fill="${C.rel}"/>`;
  s += `<text x="${mx}" y="${y1 - 14}" text-anchor="middle" font-size="14" fill="${C.sub}">${esc(r.description)}</text>`;
  if (r.technology) {
    s += `<text x="${mx}" y="${y1 + 28}" text-anchor="middle" font-size="12" font-style="italic" fill="#666666">${esc(r.technology)}</text>`;
  }
  s += '</g>';
  return s;
}

function legend(y) {
  let s = '<g font-size="13" fill="#333333">';
  s += `<rect x="90" y="${y}" width="22" height="16" rx="3" fill="${C.personBg}" stroke="${C.personBorder}" stroke-width="1.5"/>`;
  s += `<text x="120" y="${y + 13}">Person</text>`;
  s += `<rect x="230" y="${y}" width="22" height="16" rx="3" fill="${C.systemBg}" stroke="${C.systemBorder}" stroke-width="1.5"/>`;
  s += `<text x="260" y="${y + 13}">Software System</text>`;
  s += '</g>';
  return s;
}

function renderSystemContext(title, elements, relationships) {
  const persons = elements.filter(e => e.type === 'person');
  const systems = elements.filter(e => e.type === 'system');
  const boxW = 280, boxH = 170, gap = 50;
  const leftX = 90, rightX = 610, topY = 150;
  const colH = n => n * boxH + (n - 1) * gap;
  const maxColH = Math.max(colH(persons.length), colH(systems.length));
  const personTop = topY + (maxColH - colH(persons.length)) / 2;
  const systemTop = topY + (maxColH - colH(systems.length)) / 2;

  const pos = {};
  persons.forEach((p, i) => {
    const y = personTop + i * (boxH + gap);
